import React, { useState } from 'react';
import { format, subDays, subMonths, isAfter } from 'date-fns';
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Label } from "@/components/ui/label";
import { Download, FileText, Calendar, CheckSquare, Loader2 } from 'lucide-react';
import { cn } from "@/lib/utils";
import jsPDF from 'jspdf';

export default function ExportModal({ open, onClose, beliefs }) {
  const [mode, setMode] = useState('timeRange');
  const [timeRange, setTimeRange] = useState('all');
  const [selectedIds, setSelectedIds] = useState([]);
  const [isExporting, setIsExporting] = useState(false);

  const timeRanges = [
    { value: 'all', label: 'All time' },
    { value: '7days', label: 'Last 7 days' },
    { value: '30days', label: 'Last 30 days' },
    { value: '90days', label: 'Last 3 months' },
  ];

  const getFilteredBeliefs = () => {
    if (mode === 'selected') {
      return beliefs.filter(b => selectedIds.includes(b.id));
    }
    if (timeRange === 'all') return beliefs;
    const now = new Date();
    let startDate;
    if (timeRange === '7days') startDate = subDays(now, 7);
    else if (timeRange === '30days') startDate = subDays(now, 30);
    else if (timeRange === '90days') startDate = subMonths(now, 3);
    return beliefs.filter(b => isAfter(new Date(b.created_date), startDate));
  };

  const toggleBelief = (id) => {
    setSelectedIds(prev => 
      prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
    );
  };

  const selectAll = () => setSelectedIds(beliefs.map(b => b.id));
  const selectNone = () => setSelectedIds([]);

  const generatePDF = (beliefsToExport) => {
    const pdf = new jsPDF({ unit: 'mm', format: 'a4' });
    const pageWidth = 210;
    const pageHeight = 297;
    const marginLeft = 25;
    const marginRight = 25;
    const marginTop = 35;
    const marginBottom = 25;
    const contentWidth = pageWidth - marginLeft - marginRight;
    const charcoal = [55, 55, 55];
    const lightCharcoal = [100, 100, 100];
    const mutedCharcoal = [130, 130, 130];

    const addFooter = () => {
      pdf.setFont('courier', 'normal');
      pdf.setFontSize(7);
      pdf.setTextColor(...mutedCharcoal);
      pdf.text('TRACE — Your thoughts, examined', pageWidth / 2, pageHeight - 15, { align: 'center' });
    };

    const wrapText = (text, maxWidth, fontSize) => {
      pdf.setFontSize(fontSize);
      const lines = pdf.splitTextToSize(text || '', maxWidth);
      return lines;
    };

    // Cover page
    pdf.setFillColor(252, 252, 250);
    pdf.rect(0, 0, pageWidth, pageHeight, 'F');

    pdf.setFont('courier', 'normal');
    pdf.setFontSize(12);
    pdf.setTextColor(...mutedCharcoal);
    pdf.text('T R A C E', pageWidth / 2, 100, { align: 'center' });

    pdf.setFont('courier', 'normal');
    pdf.setFontSize(10);
    pdf.setTextColor(...lightCharcoal);
    pdf.text('Your thoughts, examined', pageWidth / 2, 112, { align: 'center' });

    const dates = beliefsToExport.map(b => new Date(b.created_date));
    const earliest = new Date(Math.min(...dates));
    const latest = new Date(Math.max(...dates));

    pdf.setFont('courier', 'normal');
    pdf.setFontSize(9);
    pdf.setTextColor(...mutedCharcoal);
    const dateRange = beliefsToExport.length === 1 
      ? format(earliest, 'MMMM d, yyyy')
      : `${format(earliest, 'MMMM d, yyyy')} — ${format(latest, 'MMMM d, yyyy')}`;
    pdf.text(dateRange, pageWidth / 2, 130, { align: 'center' });

    pdf.setFontSize(8);
    pdf.text(`${beliefsToExport.length} belief${beliefsToExport.length !== 1 ? 's' : ''}`, pageWidth / 2, 140, { align: 'center' });

    addFooter();

    // Belief pages
    beliefsToExport.forEach((belief) => {
      pdf.addPage();
      pdf.setFillColor(252, 252, 250);
      pdf.rect(0, 0, pageWidth, pageHeight, 'F');

      let y = marginTop;

      // Belief statement
      pdf.setFont('courier', 'normal');
      pdf.setFontSize(14);
      pdf.setTextColor(...charcoal);
      const statementLines = wrapText(belief.statement, contentWidth, 14);
      statementLines.forEach(line => {
        if (y > pageHeight - marginBottom - 20) {
          addFooter();
          pdf.addPage();
          pdf.setFillColor(252, 252, 250);
          pdf.rect(0, 0, pageWidth, pageHeight, 'F');
          y = marginTop;
        }
        pdf.text(line, marginLeft, y);
        y += 7;
      });

      y += 8;

      // Metadata
      pdf.setFont('courier', 'normal');
      pdf.setFontSize(8);
      pdf.setTextColor(...mutedCharcoal);

      const metaLines = [];
      metaLines.push(`Recorded ${format(new Date(belief.created_date), 'MMMM d, yyyy')}`);
      metaLines.push(`Confidence: ${belief.confidence} of 10`);
      if (belief.is_archived) metaLines.push('No longer held');
      if (belief.reflections?.length > 0) {
        const lastReflection = belief.reflections[belief.reflections.length - 1];
        metaLines.push(`Last revisited ${format(new Date(lastReflection.date), 'MMMM d, yyyy')}`);
      }

      metaLines.forEach(line => {
        pdf.text(line, marginLeft, y);
        y += 5;
      });

      y += 12;

      // Section helper
      const addSection = (title, content) => {
        if (!content) return;

        if (y > pageHeight - marginBottom - 40) {
          addFooter();
          pdf.addPage();
          pdf.setFillColor(252, 252, 250);
          pdf.rect(0, 0, pageWidth, pageHeight, 'F');
          y = marginTop;
        }

        pdf.setFont('courier', 'normal');
        pdf.setFontSize(8);
        pdf.setTextColor(...mutedCharcoal);
        pdf.text(title.toUpperCase(), marginLeft, y);
        y += 7;

        pdf.setFont('courier', 'normal');
        pdf.setFontSize(10);
        pdf.setTextColor(...charcoal);
        const lines = wrapText(content, contentWidth, 11);
        lines.forEach(line => {
          if (y > pageHeight - marginBottom - 10) {
            addFooter();
            pdf.addPage();
            pdf.setFillColor(252, 252, 250);
            pdf.rect(0, 0, pageWidth, pageHeight, 'F');
            y = marginTop;
          }
          pdf.text(line, marginLeft, y);
          y += 5.5;
        });

        y += 10;
      };

      addSection('Why I Believed This', belief.reasoning);
      addSection('Evidence & Experience', belief.evidence);
      addSection('What Would Change My Mind', belief.what_would_change);

      // Reflections
      if (belief.reflections?.length > 0) {
        if (y > pageHeight - marginBottom - 40) {
          addFooter();
          pdf.addPage();
          pdf.setFillColor(252, 252, 250);
          pdf.rect(0, 0, pageWidth, pageHeight, 'F');
          y = marginTop;
        }

        pdf.setFont('courier', 'normal');
        pdf.setFontSize(8);
        pdf.setTextColor(...mutedCharcoal);
        pdf.text('REFLECTION OVER TIME', marginLeft, y);
        y += 10;

        belief.reflections.forEach(ref => {
          if (y > pageHeight - marginBottom - 25) {
            addFooter();
            pdf.addPage();
            pdf.setFillColor(252, 252, 250);
            pdf.rect(0, 0, pageWidth, pageHeight, 'F');
            y = marginTop;
          }

          pdf.setFont('courier', 'normal');
          pdf.setFontSize(8);
          pdf.setTextColor(...mutedCharcoal);
          const refDate = format(new Date(ref.date), 'MMMM d, yyyy');
          const status = ref.still_believe ? 'Still believed' : 'Mind changed';
          pdf.text(`${refDate} · Confidence: ${ref.confidence_then}/10 · ${status}`, marginLeft, y);
          y += 6;

          if (ref.note) {
            pdf.setFont('courier', 'normal');
            pdf.setFontSize(9);
            pdf.setTextColor(...lightCharcoal);
            const noteLines = wrapText(ref.note, contentWidth - 5, 10);
            noteLines.forEach(line => {
              if (y > pageHeight - marginBottom - 10) {
                addFooter();
                pdf.addPage();
                pdf.setFillColor(252, 252, 250);
                pdf.rect(0, 0, pageWidth, pageHeight, 'F');
                y = marginTop;
              }
              pdf.text(line, marginLeft + 5, y);
              y += 5;
            });
          }
          y += 8;
        });
      }

      addFooter();
    });

    return pdf;
  };

  const handleExport = () => {
    setIsExporting(true);
    const beliefsToExport = getFilteredBeliefs();

    setTimeout(() => {
      const pdf = generatePDF(beliefsToExport);
      pdf.save(`TRACE-thinking-report-${format(new Date(), 'yyyy-MM-dd')}.pdf`);
      setIsExporting(false);
      onClose();
    }, 100);
  };

  const filteredCount = getFilteredBeliefs().length;

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-sm mx-auto left-[50%] translate-x-[-50%] rounded-2xl max-h-[80vh] overflow-hidden flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <FileText className="w-5 h-5 text-[#5C6B5E]" />
            Export Thinking Report
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-6 overflow-y-auto flex-1 pr-2">
          {/* Export mode */}
          <div className="space-y-3">
            <p className="text-sm font-medium text-slate-700">What to export</p>
            <div className="grid grid-cols-2 gap-2">
              <button
                onClick={() => setMode('timeRange')}
                className={cn(
                  "p-3 rounded-xl border-2 text-left transition-all",
                  mode === 'timeRange' 
                    ? "border-[#5C6B5E] bg-[#E8EDE9]" 
                    : "border-slate-200 hover:border-slate-300"
                )}
              >
                <Calendar className={cn(
                  "w-4 h-4 mb-1",
                  mode === 'timeRange' ? "text-[#5C6B5E]" : "text-slate-400"
                )} />
                <p className="font-medium text-slate-800 text-sm">By time range</p>
              </button>
              <button
                onClick={() => setMode('selected')}
                className={cn(
                  "p-3 rounded-xl border-2 text-left transition-all",
                  mode === 'selected' 
                    ? "border-[#5C6B5E] bg-[#E8EDE9]" 
                    : "border-slate-200 hover:border-slate-300"
                )}
              >
                <CheckSquare className={cn(
                  "w-4 h-4 mb-1",
                  mode === 'selected' ? "text-[#5C6B5E]" : "text-slate-400"
                )} />
                <p className="font-medium text-slate-800 text-sm">Select beliefs</p>
              </button>
            </div>
          </div>

          {/* Time range options */}
          {mode === 'timeRange' && (
            <div className="space-y-3">
              <p className="text-sm font-medium text-slate-700">Time range</p>
              <RadioGroup value={timeRange} onValueChange={setTimeRange}>
                {timeRanges.map(({ value, label }) => (
                  <div key={value} className="flex items-center space-x-3 py-2">
                    <RadioGroupItem value={value} id={value} />
                    <Label htmlFor={value} className="text-slate-700 cursor-pointer">
                      {label}
                    </Label>
                  </div>
                ))}
              </RadioGroup>
            </div>
          )}

          {/* Belief selection */}
          {mode === 'selected' && (
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <p className="text-sm font-medium text-slate-700">Select beliefs</p>
                <div className="flex gap-2">
                  <button onClick={selectAll} className="text-xs text-[#5C6B5E] hover:underline">
                    Select all
                  </button>
                  <span className="text-slate-300">|</span>
                  <button onClick={selectNone} className="text-xs text-slate-500 hover:underline">
                    Clear
                  </button>
                </div>
              </div>
              <div className="max-h-40 overflow-y-auto space-y-1 border border-slate-100 rounded-xl p-2">
                {beliefs.map(belief => (
                  <label
                    key={belief.id}
                    className="flex items-start gap-3 p-2 rounded-lg hover:bg-slate-50 cursor-pointer"
                  >
                    <Checkbox
                      checked={selectedIds.includes(belief.id)}
                      onCheckedChange={() => toggleBelief(belief.id)}
                      className="mt-0.5"
                    />
                    <div className="flex-1 min-w-0">
                      <p className="text-sm text-slate-700 line-clamp-2">{belief.statement}</p>
                      <p className="text-xs text-slate-400 mt-1">
                        {format(new Date(belief.created_date), 'MMM d, yyyy')}
                      </p>
                    </div>
                  </label>
                ))}
              </div>
            </div>
          )}

          {/* Preview count */}
          <div className="bg-slate-50 rounded-xl p-3">
            <p className="text-sm text-slate-600">
              <span className="font-semibold text-slate-800">{filteredCount}</span> belief{filteredCount !== 1 ? 's' : ''} will be exported
            </p>
          </div>
        </div>

        {/* Actions */}
        <div className="flex gap-3 pt-3 border-t border-slate-100 mt-3">
          <Button
            variant="outline"
            onClick={onClose}
            className="flex-1 h-10 rounded-xl text-sm"
          >
            Cancel
          </Button>
          <Button
            onClick={handleExport}
            disabled={filteredCount === 0 || isExporting}
            className="flex-1 h-10 rounded-xl bg-[#5C6B5E] hover:bg-[#4a574c] text-white text-sm"
          >
            {isExporting ? (
              <Loader2 className="w-5 h-5 animate-spin" />
            ) : (
              <>
                <Download className="w-4 h-4 mr-2" />
                Export PDF
              </>
            )}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}
